# Card entries: title, period, teaser, text. Order: event, person, object, fact.
TOPICS = [
 dict(slug='baltic', era=0, title='Окно на Балтику', description='Как Северная война связала новую столицу, флот и выход к морю.',
 source='https://www.prlib.ru/section/1336546',
 cards=[
 ('Ништадтский мир', '1721 год', 'Долгая война завершается договором, который меняет положение России на Балтике.',
 'Северная война между Россией и Швецией продолжалась с 1700 по 1721 год. Одной из главных целей Петра I был выход к Балтийскому морю. После тяжёлого начала русская армия добилась важных побед, а на Балтике появился флот. Война закончилась Ништадтским миром. Россия получила территории на побережье, в том числе Ингрию, Эстляндию и Лифляндию. Это укрепило положение основанного во время войны Петербурга и открыло новые возможности для морской торговли. Договор важно отличать от отдельного сражения: он юридически закреплял результат многолетнего противостояния. В том же году Пётр принял императорский титул.'),
 ('Пётр I: правитель и организатор', '1672–1725', 'За военными победами стояли верфи, обучение и перестройка управления.',
 'Пётр I связывал укрепление государства с преобразованием армии, флота и управления. Для борьбы на Балтийском море было мало собрать солдат: требовались корабли, мастера, обученные офицеры и снабжение. Поездки за границу помогали знакомиться с техническими знаниями, а строительство верфей позволяло применять их в России. Во время Северной войны Пётр участвовал в военных действиях и организации производства. Его реформы расширяли возможности государства, но требовали больших расходов и тяжёлого труда населения. Поэтому эпоху следует рассматривать с разных сторон: успехи во внешней политике были связаны с заметным ростом повинностей и усилением государственного контроля.'),
 ('Парусный корабль', 'Начало XVIII века', 'Корабль — целая система ремёсел, знаний и совместной работы.',
 'Парусный военный корабль помогает понять, почему создание флота было большой государственной задачей. Для его постройки нужны древесина, металл, парусина, канаты и работа многих мастеров. Для плавания требовались карты, знания о ветре и подготовленные моряки. Во время Северной войны Россия строила на Балтике разные типы судов: крупные парусные корабли и гребные галеры. Они решали разные задачи и не были взаимозаменяемыми. Рассматривая учебную схему, обрати внимание на мачты, паруса и корпус. Каждый элемент связан с движением и устойчивостью судна. Морская сила начиналась задолго до боя — на верфи и в учебной школе.'),
 ('Город появился до окончания войны', '1703 год', 'Петербург основали за восемнадцать лет до Ништадтского мира.',
 'Санкт-Петербург был основан в 1703 году, когда Северная война ещё продолжалась. Эта последовательность важна: новая столица не стала простым итогом уже законченной победы. Город строился в условиях продолжающегося противостояния и закреплял присутствие России в устье Невы. Его положение связывало речные пути с Балтийским морем. Позднее сюда переместился центр государственного управления. Попробуй соединить три даты: начало войны в 1700 году, основание города в 1703 году и мир в 1721 году. Такая линия времени показывает, как военные действия, строительство и политические решения происходили одновременно и влияли друг на друга.')],
 mini=('Чем завершилась Северная война?', ['Ништадтским миром', 'Тильзитским миром', 'Парижским миром 1856 года', 'Берлинским конгрессом'], 'Ништадтский мир 1721 года завершил Северную войну и закрепил приобретения России на Балтике.')),
 dict(slug='university', era=0, title='Наука выходит в город', description='Ломоносов, Московский университет и печатная книга как путь к знаниям.',
 source='https://www.prlib.ru/history/618970',
 cards=[
 ('Основание Московского университета', '1755 год', 'В Москве появляется новый центр преподавания, исследований и просвещения.',
 'В 1755 году императрица Елизавета Петровна утвердила основание Московского университета. Подготовка проекта связана с Михаилом Ломоносовым и Иваном Шуваловым. Университет должен был не только передавать знания, но и готовить людей, способных развивать науку и образование. Первоначально в нём действовали философский, юридический и медицинский факультеты. При университете появились гимназии, помогавшие подготовиться к дальнейшему обучению. Это не означало, что образование сразу стало доступным каждому: сохранялись социальные ограничения и практические трудности. Однако возникновение нового учебного центра расширяло пространство науки за пределами отдельных придворных и академических учреждений и заметно влияло на жизнь Москвы.'),
 ('Михаил Ломоносов', '1711–1765', 'Учёный, для которого развитие науки было связано с подготовкой новых исследователей.',
 'Михаил Васильевич Ломоносов занимался естественными науками, языком и литературой. Его деятельность показывает, что в XVIII веке границы между отдельными областями знания выглядели иначе, чем сегодня. Учёный стремился развивать образование в России и участвовал в подготовке проекта Московского университета. Важно помнить и об Иване Шувалове: именно совместные усилия учёного и влиятельного государственного деятеля помогли осуществить замысел. Биография Ломоносова позволяет увидеть связь личной настойчивости с устройством научных учреждений. Открытие университета стало частью более широкой задачи — создавать условия, в которых новые поколения могли учиться, работать с книгами и продолжать исследования.'),
 ('Книга университетской типографии', 'С 1756 года', 'Печатный станок помогает университету говорить с читателями за пределами аудитории.',
 'В 1756 году при Московском университете открылась типография. Печатная книга делала учебные и научные тексты доступными большему числу читателей, чем рукописное переписывание. Типография выпускала не только материалы для занятий: университетская печать участвовала в культурной жизни города. Рассматривая старую книгу, историк обращает внимание на год, место издания, имя автора и сведения об издателе. Эти детали помогают установить происхождение текста и круг его читателей. Учебная иллюстрация передаёт общий вид переплёта, а не изображает конкретный редкий экземпляр. В этом маршруте книга связывает университетскую аудиторию, труд печатника, книжную торговлю и самостоятельное чтение.'),
 ('Университет — это ещё и гимназии', 'Середина XVIII века', 'Новому учебному центру требовалась собственная система подготовки поступающих.',
 'Одного указа об открытии университета было недостаточно, чтобы в аудиториях появились подготовленные студенты. Нужны были преподаватели, книги и люди, владевшие основами необходимых предметов. При Московском университете организовали гимназии для подготовки будущих учащихся. Это показывает взаимную зависимость разных ступеней образования. Высшая школа развивалась вместе с предварительным обучением, а не отдельно от него. Вместе с тем возможности поступления зависели от положения человека в обществе: крепостные крестьяне не получили свободного доступа к этой системе. Поэтому историю просвещения полезно изучать через два вопроса одновременно: какие новые возможности возникли и какие ограничения продолжали действовать.')],
 mini=('В каком году основан Московский университет?', ['В 1755 году', 'В 1703 году', 'В 1812 году', 'В 1861 году'], 'Указ об основании Московского университета был утверждён Елизаветой Петровной в 1755 году.')),
 dict(slug='commission', era=0, title='Как обсуждали законы', description='Екатерина II, Уложенная комиссия и противоречия просвещённого правления.',
 source='https://www.prlib.ru/node/619449',
 cards=[
 ('Созыв Уложенной комиссии', '1767 год', 'Представители разных групп общества собираются для подготовки нового законодательства.',
 'В 1767 году Екатерина II созвала Уложенную комиссию. Предполагалось подготовить новый свод законов взамен устаревшего Соборного уложения 1649 года. В комиссию направляли депутатов от различных сословий и учреждений. Они привозили местные наказы, в которых излагались пожелания и жалобы. Обсуждение выявило различие интересов: единое решение не возникало автоматически из большого числа мнений. Комиссия не создала нового уложения. Её история показывает, насколько трудно было совместить идеи упорядоченного законодательства с сословным устройством и крепостным правом. Для историка важен не только итог работы, но и сохранившиеся свидетельства о том, какие проблемы считали значимыми современники.'),
 ('Екатерина II и идеи Просвещения', 'Правление: 1762–1796', 'Правительница обращалась к европейской мысли, сохраняя самодержавную власть.',
 'Екатерина II интересовалась идеями европейского Просвещения и использовала их язык, рассуждая о государстве и законах. Для Уложенной комиссии она подготовила «Наказ», в котором изложила принципы будущего законодательства. Однако знакомство с философскими идеями само по себе не превращало государство в общество равных граждан. Императрица сохраняла самодержавие, а крепостное право продолжало существовать. Поэтому при изучении её правления нужно сопоставлять заявления, проекты и реальные решения. Такой подход помогает избежать слишком простой оценки исторического деятеля. «Наказ» показывает представления Екатерины о разумном управлении, а работа комиссии позволяет увидеть трудности применения этих представлений к российскому обществу.'),
 ('«Наказ» Уложенной комиссии', '1767 год', 'Текст о принципах управления, который важно отличать от готового свода законов.',
 '«Наказ» Екатерины II был руководящим текстом для работы Уложенной комиссии. В нём обсуждались устройство государства, законодательство и принципы правосудия. Значительная часть рассуждений опиралась на идеи европейских мыслителей. Но «Наказ» не был новым уложением и не заменил действовавшие законы единым кодексом. При работе с историческим документом полезно сначала определить его назначение: проект, инструкция и принятый закон обладают разным статусом. Именно поэтому название документа и обстоятельства его создания так важны. Учебная схема показывает разворот условной книги; подлинный текст и сведения о нём можно изучить по ссылке на источник в цифровой библиотеке.'),
 ('Не все получили своего депутата', '1767–1768 годы', 'Широкое представительство не означало всеобщего политического участия.',
 'В работе Уложенной комиссии участвовали представители разных сословий, но крепостные крестьяне не выбирали собственных депутатов. Эта деталь помогает понять ограничения учреждения. Обсуждать нужды населения и предоставлять всем равное участие — разные вещи. Даже многочисленное собрание могло отражать интересы одних групп лучше, чем других. Наказы депутатам показывали разнообразие местных проблем, однако не устраняли зависимость людей от их сословного положения. Сравни эту ситуацию с современным представлением о равенстве избирателей, не перенося современные правила прямо в прошлое. Исторический вопрос состоит в том, кто имел право говорить от своего имени и чьи интересы передавались через других людей.')],
 mini=('Для чего созвали Уложенную комиссию?', ['Для подготовки нового свода законов', 'Для строительства флота', 'Для открытия первой железной дороги', 'Для проведения земской реформы'], 'Уложенная комиссия должна была подготовить новое уложение. Итогового свода законов она не создала.')),
 dict(slug='war-1812', era=1, title='Испытание 1812 года', description='Бородино, Кутузов и решения, от которых зависела судьба армии.',
 source='https://www.prlib.ru/collections/467016',
 cards=[
 ('Бородинское сражение', '26 августа (7 сентября) 1812 года', 'Крупнейшая битва кампании не завершила войну одним ударом.',
 'Бородинское сражение произошло во время вторжения армии Наполеона в Россию. Русской армией командовал Михаил Кутузов. Бой был исключительно тяжёлым и сопровождался большими потерями с обеих сторон. При этом ни сам бой, ни занятие Москвы французами не означали окончания всей кампании. Русская армия сохранилась и продолжила действовать. Изучая сражение, важно различать удержание отдельных позиций, состояние войск после боя и дальнейший ход войны. Событие не помещается в простую формулу одного решающего удара. Оно стало частью длительного противостояния, в котором значение имели снабжение, расстояния, управление войсками и способность сохранять силы для следующих действий.'),
 ('Михаил Кутузов', 'Кампания 1812 года', 'Главнокомандующий выбирал между защитой важных мест и сохранением армии.',
 'Михаил Илларионович Кутузов имел большой военный опыт и в 1812 году возглавил русские армии. Его деятельность в этой кампании связана с Бородинским сражением, решением оставить Москву и последующими действиями против наполеоновских войск. Военное командование требовало учитывать противоречивые обстоятельства: ожидания общества, потери, снабжение и состояние солдат. Поэтому решение полководца нельзя оценивать только по движению линии на карте. Сохранение армии позволяло продолжать сопротивление даже после оставления крупного города. Биография Кутузова в этом маршруте помогает увидеть войну как последовательность сложных решений, где последствия не всегда были очевидны участникам в момент выбора.'),
 ('Карта военной кампании', '1812 год', 'Линии на карте показывают пространство решений, а не только направление наступления.',
 'Военная карта помогает соединить отдельные эпизоды кампании в пространстве. На ней можно отметить Бородино, Москву, Тарутино и пути дальнейшего отступления французской армии. Однако схема не передаёт всего: она обычно не показывает усталость людей, нехватку продовольствия и состояние дорог. Расстояние между точками важно читать вместе со временем, которое требовалось на переход. При изучении карты спроси себя, откуда войска могли получать снабжение и какие пути оставались доступными. Учебная иллюстрация условна и не предназначена для определения точных позиций частей. Её задача — показать, почему география была существенной частью военного планирования.'),
 ('Оставить столицу — не закончить войну', 'Сентябрь 1812 года', 'После оставления Москвы русская армия сохранила возможность продолжать борьбу.',
 'После Бородинского сражения русская армия отступила и оставила Москву. На военном совете в Филях обсуждалось, стоит ли принимать ещё один бой для защиты города. Кутузов принял решение сохранить армию. Это было тяжёлое решение, но занятие Москвы не заставило Россию заключить мир. Французские войска столкнулись с трудностями снабжения и в дальнейшем покинули город. История напоминает, что символическая важность места и военное положение не всегда совпадают. Чтобы понять ход кампании, нужно следить за состоянием обеих армий и их возможностями продолжать действия, а не считать занятие одного города автоматическим завершением войны.')],
 mini=('Кто командовал русской армией при Бородине?', ['Михаил Кутузов', 'Пётр I', 'Сергей Витте', 'Франц Герстнер'], 'В Бородинском сражении русской армией командовал Михаил Илларионович Кутузов.')),
 dict(slug='decembrists', era=1, title='Спор о будущем страны', description='Декабристы: политические проекты, выступление и цена неудачи.',
 source='https://www.prlib.ru/history/619844',
 cards=[
 ('Выступление на Сенатской площади', '14 (26) декабря 1825 года', 'Политический замысел сталкивается с неудачей вооружённого выступления.',
 'В декабре 1825 года участники тайных обществ организовали выступление в Петербурге. Смерть Александра I и неопределённость с наследованием престола создали ситуацию, которую заговорщики попытались использовать. На Сенатскую площадь вышли войска, однако согласованного осуществления плана не получилось. Восстание было подавлено. Его участники стремились изменить государственное устройство, но их проекты и представления о путях перемен различались. Поэтому декабристов не следует считать группой с полностью единой программой. Событие важно изучать вместе с политическими идеями, подготовкой и последствиями. Одной даты недостаточно, чтобы понять, почему возникло движение и почему его действия не привели к намеченному результату.'),
 ('Никита Муравьёв', '1795–1843', 'Один из участников движения предложил проект конституционного устройства.',
 'Никита Михайлович Муравьёв был участником декабристского движения и автором конституционного проекта. Он связывал преобразование России с ограничением верховной власти и установлением правовых правил. Его взгляды отличались от республиканского проекта Павла Пестеля. Это различие показывает, что общее недовольство существующим порядком не обязательно означает согласие о будущем устройстве страны. Для историка политическая программа — источник сведений о целях и представлениях её автора, а не описание уже осуществлённой реформы. Сравнивая проекты, полезно отдельно рассмотреть устройство власти, положение крестьян и способы проведения перемен. Так становятся видны и общие стремления участников, и важные разногласия внутри движения.'),
 ('Рукопись политического проекта', '1820-е годы', 'Документ позволяет увидеть, какое будущее представлял его автор.',
 'Рукописный проект конституции — пример источника, по которому изучают политические идеи. В отличие от воспоминаний о событии, он описывает желаемый порядок: какие органы должны управлять государством, как ограничить их полномочия и какие права закрепить. Но проект не равен действующему закону. Чтобы правильно использовать такой документ, нужно знать автора, время создания и обстоятельства распространения. В декабристском движении существовали разные программные тексты. Их сравнение помогает не подменять разнообразие идей единой готовой формулой. Учебная иллюстрация изображает условные листы рукописи; она не выдаётся за факсимиле конкретного документа из следственного дела.'),
 ('Одна дата — два календаря', '14 / 26 декабря 1825 года', 'Разные числа могут обозначать один и тот же исторический день.',
 'Выступление декабристов часто датируют 14 декабря 1825 года. В записи по григорианскому календарю это 26 декабря. В Российской империи тогда использовался юлианский календарь, который в XIX веке отставал от григорианского на двенадцать дней. Две даты в скобках поэтому не означают два разных восстания. При сравнении источников всегда проверяй, по какому календарю дана дата. Это особенно полезно, если российское событие сопоставляется с иностранной перепиской или современной памятной датой. Расстояние между календарями менялось со временем, поэтому нельзя автоматически переносить разницу в двенадцать дней на любой другой век и любое событие.')],
 mini=('Где произошло выступление декабристов в декабре 1825 года?', ['На Сенатской площади в Петербурге', 'На Бородинском поле', 'В Ништадте', 'На вокзале Царского Села'], '14 (26) декабря 1825 года выступление произошло на Сенатской площади в Санкт-Петербурге.')),
 dict(slug='railway', era=1, title='Первый поезд', description='Как Царскосельская железная дорога знакомила Россию с новым транспортом.',
 source='https://www.prlib.ru/history/619711',
 cards=[
 ('Открытие Царскосельской дороги', '1837 год', 'Петербург и Царское Село связывает общественная железная дорога.',
 'В 1837 году открылась Царскосельская железная дорога. Она соединила Петербург с Царским Селом; затем движение дошло до Павловска. Этот проект стал важным ранним опытом общественного железнодорожного сообщения в России. Паровая тяга позволяла перевозить пассажиров иначе, чем привычные конные экипажи. Но дорога означала не только покупку паровоза: требовались рельсы, станции, расписание и обслуживание. Её сравнительно небольшая протяжённость помогала проверить новую технологию на практике. Позднее железные дороги стали связывать большие расстояния. При этом важно отличать общественную линию для перевозок от более ранних промышленных путей и отдельных опытов с паровыми машинами.'),
 ('Франц Антон Герстнер', '1796–1840', 'Инженер участвовал в продвижении и устройстве нового вида сообщения.',
 'Франц Антон Герстнер был инженером и одним из ключевых организаторов Царскосельской железной дороги. Его работа требовала не только технических знаний, но и умения обосновать пользу проекта перед властями и будущими инвесторами. Новая транспортная система вызывала вопросы: выдержит ли техника климат, будет ли достаточно пассажиров, как организовать безопасность движения. Проверить ожидания можно было в ходе строительства и эксплуатации. История Герстнера помогает увидеть роль специалиста, соединяющего расчёт, организацию и публичное объяснение замысла. Железная дорога не появилась сама по себе после изобретения паровой машины: для её создания понадобились решения многих людей и согласование разных интересов.'),
 ('Паровоз', '1830-е годы', 'Пар превращается в движение, а движение требует целой инфраструктуры.',
 'Паровоз использует энергию пара для движения колёс. Топливо нагревает воду в котле, пар действует на механизм, а тот передаёт усилие колёсам. В учебной схеме выделены котёл, дымовая труба и ходовая часть. Однако работающий локомотив сам по себе ещё не создаёт железнодорожного сообщения. Нужны прочный путь, запасы воды и топлива, подготовленные машинисты и ремонт. Именно эта система делает отдельную машину частью транспорта. Сравни паровоз с парусным кораблём из другой эпохи: в обоих случаях видимый механизм опирается на труд множества людей. Отличаются источник движения и среда, но сохраняется зависимость техники от организации.'),
 ('Новая привычка — жить по расписанию', 'С 1837 года', 'Железная дорога меняла не только скорость поездки, но и организацию путешествия.',
 'Регулярное железнодорожное сообщение требует согласованного времени отправления и прибытия. Пассажир должен заранее прийти на станцию, купить билет и ориентироваться в расписании. Для работников дороги точность связана также с безопасностью и использованием пути. Поэтому история транспорта — это история новых повседневных привычек. Время поездки становится частью общего плана, которому подчиняется множество незнакомых людей. Царскосельская дорога позволяла познакомиться с такой организацией движения на коротком маршруте. Не стоит представлять, будто вся страна сразу перешла на единый железнодорожный ритм: распространение сети и изменение привычек происходили постепенно и неодинаково в разных местах.')],
 mini=('В каком году открылась Царскосельская железная дорога?', ['В 1837 году', 'В 1721 году', 'В 1755 году', 'В 1891 году'], 'Общественное движение по Царскосельской железной дороге открылось в 1837 году.')),
 dict(slug='emancipation', era=2, title='Свобода и её условия', description='Отмена крепостного права: личная свобода, земля и незавершённые перемены.',
 source='https://bigenc.ru/c/krest-ianskaia-reforma-1861-db5085',
 cards=[
 ('Отмена крепостного права', '19 февраля (3 марта) 1861 года', 'Крестьяне получают личную свободу, но земельный вопрос остаётся сложным.',
 'В 1861 году Александр II подписал документы об освобождении помещичьих крестьян от крепостной зависимости. Они получали личную свободу и ряд гражданских прав. Однако освобождение нельзя понимать как немедленную и бесплатную передачу всей обрабатываемой земли. Размеры наделов, повинности и выкуп регулировались особыми правилами. На переходный период сохранялось временнообязанное состояние. Реформа изменила правовое положение миллионов людей, но не устранила все социальные противоречия деревни. Поэтому её последствия нужно рассматривать отдельно в вопросах личной зависимости, землевладения и хозяйства. Такое разделение помогает увидеть масштаб перемены и одновременно понять, почему после объявления свободы крестьянский вопрос не исчез.'),
 ('Александр II', '1818–1881', 'При этом императоре началась серия преобразований, известных как Великие реформы.',
 'Александр II вступил на престол в 1855 году. С его правлением связаны отмена крепостного права и другие крупные преобразования, включая земскую и судебную реформы. Решение об освобождении крестьян готовилось в условиях сложных споров о земле, собственности и будущем государства. Император подписывал итоговые документы, но содержание реформ вырабатывали также чиновники, комиссии и общественные деятели. Поэтому историю преобразований нельзя свести к единственному личному поступку правителя. Она показывает взаимодействие государственной власти и социальных интересов. При этом самодержавное устройство сохранялось: изменения в отдельных областях жизни не означали перехода к парламентской системе управления или всеобщему политическому равенству.'),
 ('Уставная грамота', 'После 1861 года', 'Общие правила реформы должны были превратиться в конкретные условия на местах.',
 'Уставная грамота фиксировала условия отношений между помещиком и освобождаемыми крестьянами: наделы и связанные с ними повинности. Такой документ помогает понять, как общая реформа действовала в конкретном имении. Законодательное провозглашение свободы и повседневное устройство землепользования были разными уровнями перемен. Для изучения грамоты важно знать местность, состав участников и применявшиеся нормы. Один документ не описывает автоматически положение всех крестьян империи. Сравнение местных источников позволяет увидеть различия. В нашей иллюстрации показан условный официальный лист, а не подлинная грамота. Исторические документы требуют внимательного чтения: одинаковые слова могут обозначать вполне определённые правовые обязанности и ограничения.'),
 ('Личная свобода и земля — разные вопросы', '1861 год и последующие десятилетия', 'Отмена зависимости не означала, что все земельные расчёты закончились в тот же день.',
 'После реформы 1861 года крестьянин больше не был крепостным человеком помещика. Но правила пользования землёй и перехода к выкупу устанавливались отдельно. До выкупной операции временнообязанные крестьяне несли определённые повинности за надел. Эта деталь объясняет, почему последствия реформы растянулись на многие годы. В учебном рассказе удобно различать три вопроса: свободен ли человек лично, на каких условиях он пользуется землёй и какие платежи обязан вносить. Если соединить их в одно утверждение, легко получить ошибочную картину мгновенного решения всех проблем. Сложность реформы состояла именно в одновременном изменении прав, хозяйственных отношений и привычного уклада деревни.')],
 mini=('Что крестьяне получили по реформе 1861 года?', ['Личную свободу', 'Всеобщие выборы императора', 'Бесплатно всю помещичью землю', 'Отмену любых платежей в тот же день'], 'Реформа дала личную свободу. Земельные отношения и выкупные платежи регулировались отдельно.')),
 dict(slug='zemstvo', era=2, title='Кто заботится о повседневном', description='Земства, местные дороги, школы и медицина во второй половине XIX века.',
 source='https://www.prlib.ru/history/618939',
 cards=[
 ('Земская реформа', '1864 год', 'Появляются выборные учреждения для решения части местных хозяйственных вопросов.',
 'Земская реформа 1864 года создала в ряде губерний выборные органы местного самоуправления. Земства занимались хозяйственными задачами: дорогами, школами, медициной и другими нуждами территории. Они действовали на уездном и губернском уровнях. Это не был парламент всей страны, и земства не заменяли государственную власть. Их самостоятельность ограничивалась законом и административным надзором. Представительство также не было равным: устройство выборов давало значительное влияние землевладельцам. Тем не менее земские учреждения создали пространство практической местной работы. Их историю можно изучать через конкретные решения: где открыть школу, как содержать дорогу и каким образом обеспечить медицинскую помощь жителям отдалённых селений.'),
 ('Земский врач', 'Вторая половина XIX века', 'Медицинская помощь стала одной из заметных областей местной общественной работы.',
 'Земский врач работал в системе медицинской помощи, которую организовывали и поддерживали земства. Ему нередко приходилось обслуживать большой участок и сталкиваться с нехваткой времени, средств и персонала. Такая работа включала не только лечение отдельных пациентов, но и вопросы предупреждения болезней и санитарного состояния населённых мест. Здесь важно видеть связь профессии с учреждениями: даже подготовленному специалисту нужны помещение, инструменты и финансирование. Земская медицина развивалась неодинаково по регионам и не охватывала сразу всех жителей страны. Образ врача помогает рассмотреть реформу со стороны повседневной жизни: изменения проявлялись в том, мог ли конкретный человек получить помощь рядом со своим домом.'),
 ('Врачебная сумка', 'Вторая половина XIX века', 'Небольшой предмет напоминает о больших расстояниях между врачом и пациентом.',
 'Врачебная сумка позволяла перевозить инструменты и необходимые принадлежности к месту осмотра. Она помогает представить подвижный характер медицинской работы на большой территории. Но содержимое сумки менялось со временем, а знания и методы врача XIX века отличались от современных. Поэтому учебную иллюстрацию нельзя использовать как инструкцию по лечению или точную реконструкцию набора определённого врача. Для историка предмет интересен в связи с условиями труда: как добирались до пациента, что можно было взять с собой и какая помощь требовала больницы. Через такую вещь удобно перейти от общего понятия земской реформы к конкретным людям и их повседневным задачам.'),
 ('Местное управление не было всеобщим', 'После 1864 года', 'Наличие выборов ещё не означало равного участия всех жителей.',
 'Земские учреждения часто называют выборными органами, но это определение требует пояснения. Выборы строились с учётом сословных и имущественных различий. Разные группы населения имели неодинаковые возможности влиять на состав собраний. Кроме того, земства вводились не во всех частях империи одновременно и находились под надзором администрации. Эти ограничения не отменяют значения местной работы, но помогают точнее описать устройство системы. Изучая реформу, разделяй два вопроса: какие задачи учреждение решало и кто участвовал в принятии решений. Земства могли улучшать школы и медицину, оставаясь при этом частью государства с самодержавной властью и неравным представительством населения.')],
 mini=('Какую задачу решали земства?', ['Организацию местных школ и медицинской помощи', 'Объявление войны другим государствам', 'Выборы императора', 'Управление всей внешней политикой'], 'Земства занимались местным хозяйством, в том числе школами, дорогами и медициной.')),
 dict(slug='transsib', era=2, title='Дорога через континент', description='Начало Транссиба: инженерная задача, государственный проект и новые связи.',
 source='https://railways.projects.mintrans.ru/19.html',
 cards=[
 ('Начало строительства Транссиба', '1891 год', 'Великий Сибирский путь должен связать огромные пространства железной дорогой.',
 'В 1891 году началось строительство Транссибирской магистрали — Великого Сибирского пути. Проект был призван связать европейскую часть России с Сибирью и Дальним Востоком. Работы велись поэтапно на разных участках. Инженерам и рабочим приходилось учитывать реки, рельеф, климат и большие расстояния доставки материалов. Дорога меняла условия перевозок, переселения и торговли, но эти изменения не происходили одномоментно. Начало строительства важно отличать от завершения всей системы и появления непрерывного движения по полностью российской территории. В нашем маршруте рассматривается прежде всего замысел конца XIX века и масштаб задачи, которая продолжала решаться уже в следующем столетии.'),
 ('Сергей Витте', '1849–1915', 'Развитие железных дорог было частью его представлений об экономическом росте.',
 'Сергей Юльевич Витте был государственным деятелем, тесно связанным с развитием железных дорог и финансовой политикой России. В конце XIX века он занимал важные министерские должности и поддерживал строительство Сибирского пути. Железнодорожная сеть рассматривалась как средство соединить рынки, ускорить перевозки и укрепить хозяйственные связи. Но крупный проект требовал значительных средств и решений о том, какие направления считать первоочередными. Биография Витте показывает связь транспорта с финансами и государственным управлением. Дорога была не только инженерным сооружением: её развитие зависело от бюджета, организации труда и политических целей. При этом её повседневное строительство осуществляли многие специалисты и рабочие.'),
 ('Рельс и шпала', 'Конец XIX века', 'Тысячи километров дороги складывались из повторяющихся деталей и постоянного обслуживания.',
 'Рельсы направляют движение колёс, а шпалы поддерживают их положение и передают нагрузку основанию пути. Эта простая на вид конструкция требует точных размеров, надёжных материалов и регулярного ухода. Для длинной магистрали важен не один удачно построенный участок, а одинаково пригодная для движения цепочка участков, мостов и станций. Поэтому массовое производство и доставка деталей были существенной частью проекта. Учебная схема выделяет элементы пути и не является чертежом для строительства. Рассматривая её, попробуй представить, сколько раз такую конструкцию нужно повторить на огромном расстоянии. Через отдельную деталь становится понятнее масштаб труда, скрытый за короткой линией на карте.'),
 ('Одна магистраль — много этапов', '1891 год — начало XX века', 'У большого инфраструктурного проекта не всегда есть одна простая дата завершения.',
 'Транссибирскую магистраль строили по участкам, и возможности движения менялись по мере их ввода. В разные годы существовали разные маршруты и временные способы преодоления отдельных препятствий. Поэтому вопрос о завершении требует уточнения: идёт ли речь о начале сообщения, непрерывном рельсовом пути или линии целиком по российской территории. Последнее обычно связывают с завершением Амурской дороги в 1916 году. Эта дата выходит за границы начальной экспозиции, но помогает понять продолжение процесса. История Транссиба учит внимательно читать формулировки. Начало проекта в XIX веке и окончательное соединение отдельных частей транспортной системы — разные события в одном длительном развитии.')],
 mini=('В каком году началось строительство Транссибирской магистрали?', ['В 1891 году', 'В 1767 году', 'В 1812 году', 'В 1837 году'], 'Начало строительства Великого Сибирского пути относится к 1891 году. Работы продолжались и в XX веке.')),
]

